/**
 * Loads the expert bench and the need-area definitions.
 *
 * data/clinicians.json is generated by scripts/build_clinicians.py from the two
 * files Ignition supply; data/areas.json is hand-maintained. Both are read once
 * at startup and held in memory - the bench is 35 records and changes a handful
 * of times a year.
 */

import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import type { Area, Clinician, Stage } from "../shared/types.ts";

const DATA_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "data");

export interface Bench {
  clinicians: Clinician[];
  areas: Area[];
  stages: Stage[];
}

/**
 * Where an updated bench is written.
 *
 * The copy baked into the image is read-only across redeploys, so anything the
 * admin page saves has to land on the mounted volume or it disappears the next
 * time the container is rebuilt. Falls back to the image copy on first start,
 * before anyone has uploaded anything.
 */
export const BENCH_PATH = process.env.BENCH_PATH ?? join(DATA_DIR, "clinicians.json");

/** Where uploaded headshots are written. Same reasoning as BENCH_PATH: the
 *  image copy is read-only across redeploys. */
export const HEADSHOTS_PATH = process.env.HEADSHOTS_PATH ?? join(DATA_DIR, "headshots");

/**
 * Read-only source for the initial bench.
 *
 * The published image deliberately contains no clinician data - emails,
 * biographies and photographs of 35 real people do not belong in a container
 * registry, where they would spread into layer caches and CI runners. The VPS
 * mounts them from the private repository checkout instead, and the first
 * upload at /admin writes to the volume from then on.
 */
export const SEED_DIR = process.env.SEED_DIR ?? DATA_DIR;

/**
 * An empty bench is a legitimate state, not an error.
 *
 * The published image ships with no clinician data at all - emails,
 * biographies and photographs of 35 real people have no business in a
 * container registry. A fresh deployment therefore starts empty, and the
 * organiser uploads the two source documents at /admin. Everything downstream
 * has to cope with that first-run window rather than crash-looping through it.
 */
export function loadBench(dir = DATA_DIR): Bench {
  // Volume first (anything an organiser uploaded), then the mounted seed, then
  // the image copy for local development.
  const candidates = [BENCH_PATH, join(SEED_DIR, "clinicians.json"), join(dir, "clinicians.json")];
  const source = candidates.find((p) => existsSync(p));
  const clinicians: Clinician[] = source ? JSON.parse(readFileSync(source, "utf8")) : [];
  // areas.json is configuration, not personal data, so it ships in the image.
  const areasPath = [join(SEED_DIR, "areas.json"), join(dir, "areas.json")].find((p) =>
    existsSync(p),
  );
  const areasFile = JSON.parse(readFileSync(areasPath ?? join(dir, "areas.json"), "utf8"));
  const areas: Area[] = areasFile.areas;
  const stages: Stage[] = areasFile.stages ?? [];

  // Areas are configuration and ship in the image, so their absence really is
  // a broken deployment.
  if (!areas.length) throw new Error("no need areas defined in areas.json");

  // A likelyGaps entry pointing at a renamed area would silently stop
  // influencing anything, so fail loudly instead.
  const areaIds = new Set(areas.map((a) => a.id));
  for (const stage of stages) {
    const bad = stage.likelyGaps.filter((g) => !areaIds.has(g));
    if (bad.length) {
      throw new Error(`stage "${stage.id}" references unknown areas: ${bad.join(", ")}`);
    }
  }

  return { clinicians, areas, stages };
}

/** Need areas that no active clinician covers. Founders scoring weakest in one
 *  of these get nothing back for it, so it belongs in the organiser view. */
export function unreachableAreas(bench: Bench): Area[] {
  return bench.areas.filter(
    (a) => !bench.clinicians.some((c) => c.active && c.tags.some((t) => a.tags.includes(t))),
  );
}

/**
 * Areas ordered by how thinly the bench covers them, for the organiser view.
 *
 * A plain headcount flatters the bench. Pitch & story has three clinicians who
 * match at least one of its tags, but one of them covers three tags and the
 * other two cover one apiece - it is really one specialist plus two people who
 * touch the subject. `specialists` counts clinicians matching more than one tag,
 * which is the number worth staffing against.
 */
export function coverage(
  bench: Bench,
): { area: Area; experts: number; specialists: number }[] {
  return bench.areas
    .map((area) => {
      const matched = bench.clinicians
        .filter((c) => c.active)
        .map((c) => c.tags.filter((t) => area.tags.includes(t)).length)
        .filter((n) => n > 0);
      return {
        area,
        experts: matched.length,
        specialists: matched.filter((n) => n > 1).length,
      };
    })
    .sort((a, b) => a.specialists - b.specialists || a.experts - b.experts);
}
